script:
test("weekend gap does not reset a three day absence streak", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" }
  ]);
  assert.equal(actual, "2024-01-08");
});

test("a present day resets the count before it reaches 3", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" }
  ]);
  assert.equal(actual, null);
});

test("a fourth absence in the same streak does not change the date", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ]);
  assert.equal(actual, "2024-01-08");
});

test("only the first streak that reaches 3 is returned", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "present" },
    { date: "2024-01-12", status: "absent" },
    { date: "2024-01-15", status: "absent" },
    { date: "2024-01-16", status: "absent" }
  ]);
  assert.equal(actual, "2024-01-10");
});

test("an empty list returns nothing", function () {
  var actual = code.firstThreeDayAbsenceStreak([]);
  assert.equal(actual, null);
});

test("exactly two absences stay below the threshold", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ]);
  assert.equal(actual, null);
});

test("a single absence does not reach 3", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-08", status: "absent" }
  ]);
  assert.equal(actual, null);
});

test("all present days keep the count at zero", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "present" },
    { date: "2024-01-10", status: "present" }
  ]);
  assert.equal(actual, null);
});

test("a removed holiday gap does not reset the streak", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-02-16", status: "absent" },
    { date: "2024-02-26", status: "absent" },
    { date: "2024-02-27", status: "absent" }
  ]);
  assert.equal(actual, "2024-02-27");
});

test("a present day first means the third absence is the last item", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" }
  ]);
  assert.equal(actual, "2024-01-11");
});

test("a present day in the middle resets before either run reaches 3", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "present" },
    { date: "2024-01-11", status: "absent" },
    { date: "2024-01-12", status: "absent" }
  ]);
  assert.equal(actual, null);
});

test("the date is kept when the streak later resets", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" },
    { date: "2024-01-12", status: "present" },
    { date: "2024-01-15", status: "absent" },
    { date: "2024-01-16", status: "present" }
  ]);
  assert.equal(actual, "2024-01-11");
});

test("a streak can reach 3 on the first day of a month", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-03-28", status: "absent" },
    { date: "2024-03-29", status: "absent" },
    { date: "2024-04-01", status: "absent" }
  ]);
  assert.equal(actual, "2024-04-01");
});

test("a streak can reach 3 on the last day of a month", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-09-26", status: "absent" },
    { date: "2024-09-27", status: "absent" },
    { date: "2024-09-30", status: "absent" }
  ]);
  assert.equal(actual, "2024-09-30");
});

test("a year boundary does not reset the streak", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2023-12-28", status: "absent" },
    { date: "2023-12-29", status: "absent" },
    { date: "2024-01-01", status: "absent" }
  ]);
  assert.equal(actual, "2024-01-01");
});

test("leap day can be the day the count reaches 3", function () {
  var actual = code.firstThreeDayAbsenceStreak([
    { date: "2024-02-26", status: "absent" },
    { date: "2024-02-27", status: "absent" },
    { date: "2024-02-29", status: "absent" }
  ]);
  assert.equal(actual, "2024-02-29");
});
